from save_review import save
save(1196,{2:'超级破片火箭发射器是原铸星际战士寂灭小队使用的一种武器，用于发射破片导弹。',4:'Desolation Squad Superfrag Rocket Launcher 寂灭小队的超级破片火箭发射器',7:'它的有效射程甚至超过狙击步枪，对密集敌群极为有效。一次击发便能将目标区域化为冒烟的弹坑。发射器还附带一具弹链供弹的堡主发射器，可以独立开火。'})
save(1197,{2:'超级穿甲火箭发射器是原铸星际战士寂灭小队使用的一种武器，用于发射穿甲导弹。',4:'Desolation Squad Superkrak Rocket Launcher 寂灭小队的超级穿甲火箭发射器',7:'它适合对付装甲突击集群或大型生物，能够利落地贯穿各类装甲外壳。武器还附带一具弹链供弹的堡主发射器，可以独立开火。'},title='超级穿甲火箭发射器 Superkrak Rocket Launcher')
save(1198,{2:'旋风导弹发射器是专门为终结者装甲设计的导弹发射器改型。',6:'旋风导弹发射器由两个联动的立方形导弹箱组成，可装填穿甲与破片导弹，并配有瞄准器和传感器阵列。导弹与传感器组件安装在标准终结者装甲背部，让星际战士在使用发射器时，仍能同时持有风暴爆矢枪与动力拳。旧式设计则要求终结者手持传感器阵列，牺牲了装备动力拳的空间，却能获得更高的精度。',8:'这种武器的前身安装在标枪突击速攻艇上；这些源自大远征时代的反重力载具作为遗物留存至第41个千年，仍在使用该型号。'},terms=[('Cyclone Missile Launcher','旋风导弹发射器')])
save(1199,{2:'长弓发射器是大远征和荷鲁斯之乱期间，星际战士西卡然长弓火炮坦克使用的一种先进导弹发射器。',6:'长弓发射器以剑尾攻击机的旋转导弹发射器为基础。西卡然车体提供了更大的安装空间，因此可采用更复杂的供弹机构，并兼容多种弹头。岁月流逝，这些先进系统逐渐损坏；到第41个千年，西卡然长弓坦克通常只能改装更简单的旋转导弹系统。'},terms=[('Arcus Launcher','长弓发射器')])
save(1200,{2:'复仇发射器是星际战士风暴鹰炮艇的武器之一，由多腔火箭发射装置组成，使用反人员破片弹对目标区域实施饱和轰击。它专为近距离战斗设计，既能扫清着陆区，也能为炮艇运送到战场的星际战士提供火力支援。'},terms=[('Vengeance Launcher','复仇发射器')])
save(1201,{2:'三头犬发射器是一种帝国武器，通常安装在星际战士风暴型兰德速攻艇上。它有三根发射管，可发射破片火箭或眩晕火箭。'},terms=[('Cerberus Launcher','三头犬发射器')])
save(1202,{2:'天矛导弹发射器是安装在星际战士猎手战车上的地对空武器，能够齐射多枚导弹。每枚天矛导弹内都封存着一名战团农奴的遗骸，利用其大脑强化先进的瞄准系统，引导导弹命中目标。',6:'天矛导弹威力强大，既能炸毁钛族梭鱼战机，也能击落灵族吸血鬼掠袭者，甚至足以消灭嗜血狂魔和虫巢暴君。',8:'天矛导弹发射器也可作为固定防空设施，接入更大规模的防空网络。'},terms=[('Skyspear Missile Launcher','天矛导弹发射器'),('Skyspear Missile','天矛导弹')])
save(1203,{2:'天锤导弹发射器是星际战士风暴爪炮艇搭载的导弹武器平台，能齐射超高速导弹，猛烈撞击目标，是理想的反坦克武器。'},terms=[('Skyhammer Missile Launcher','天锤导弹发射器')])
save(1204,{2:'锤击导弹发射器是一套安装在星际战士锤击型风暴速攻艇上的导弹发射阵列。'},terms=[('Hammerstrike Missile Launcher','锤击导弹发射器')])
save(1205,{2:'死风导弹发射器是星际战士空降舱可搭载的武器，以它替换标准风暴爆矢枪后，便能提供短距离爆炸火力支援。',4:'这类武器还可大批部署，组成死风轨道打击部队。',6:'Drop Pod with Deathwind missile launchers 配备死风导弹发射器的空降舱'},terms=[('Deathwind missile launcher','死风导弹发射器'),('Deathwind Orbital Strike Force','死风轨道打击部队')])
save(1206,{},terms=[('Hammerfall Missile Launcher','落锤导弹发射器')])
save(1207,{2:'剑尾旋转导弹发射器是帝国剑尾型截击机搭载的一种导弹发射器。',6:'这种致命系统是重型虚空战斗机常用设计的紧凑版本，以旋转弹匣为快速发射装置供弹，弹药配有先进的集束装药弹头和内置追踪探测系统。它的主要用途是摧毁敌方战机，杀伤效率极高，也能灵活转用于攻击地面装甲目标。',8:'旋转导弹发射器可适配破片导弹、穿甲导弹或猎杀者导弹。'}, {2:'原句launched from疑误，应为搭载于飞机，不能译成把发射器本身发射出去。',6:'auguries在设备语境指探测装置，原“追踪预兆”不通。'},[('Xiphon Rotary Missile Launcher','剑尾旋转导弹发射器'),('Hunter-Killer Missile','猎杀者导弹')])
save(1208,{2:'许珀里翁导弹发射器是星际战士许珀里翁型旋风战车使用的专用防空武器，可向快速低飞的目标发射多达二十枚导弹，尤其适合拦截实施扫射的对地攻击机。',4:'星际战士战团兵力有限，难以编成专门的防空部队，因此常以配有遥控启动装置的自动化许珀里翁发射器承担局地防空任务。这些平台由雷鹰炮艇运送投放，交由战团科技战士启动，再通过指挥车监控。',9:'许珀里翁防空导弹的工作原理与猎杀者导弹相似。弹内追踪设备锁定目标，将信息传给逻辑引擎；发射后，逻辑引擎控制舵翼，跟随目标运动、绕过障碍，直至命中。为拦截高速目标，燃料占了导弹重量的大部分，使其能在短距离内高速飞行。但它的燃料不足以攻击高空目标，此类任务更适合交由蝎尾狮防空导弹执行。',11:'追踪设备用途广泛，因此许珀里翁导弹也能攻击地面目标，不过星际战士指挥官通常只在不得已时这样使用。'},terms=[('Hyperios Missile Launcher','许珀里翁导弹发射器'),('Hyperios Missile','许珀里翁导弹')])
save(1209,{2:'旋风多管导弹发射器安装在星际战士旋风战车上，可发射多种导弹，其中最常见的是标准复仇导弹和燃烧堡主导弹。',6:'旋风可装载不同弹种，但同一轮射击只能使用一种。底稿所述的较新型号有两种配置：一种有两个发射舱，每舱五枚导弹，以两枚一组联动发射；另一种装填更大的导弹，两个舱各容纳两枚，每次单发。'},terms=[('Whirlwind multiple missile launcher','旋风多管导弹发射器')])
save(1210,{2:'火箭吊舱又称多管火箭吊舱，最常搭载于秃鹫炮艇、女武神炮艇等帝国飞行器上。',6:'它们发射大量小型破片火箭，以致命破片覆盖大片区域。这是一类反步兵武器，对密集聚集、装甲防护薄弱的敌人尤其有效。'},terms=[('Rocket Pod','火箭吊舱'),('Multiple Rocket Pod','多管火箭吊舱')])
save(1211,{2:'伊卡洛斯火箭舱是一种火箭吊舱，安装在原铸星际战士的雷击型风暴速攻艇和救赎者无畏机甲上。'},terms=[('Icarus Rocket Pod','伊卡洛斯火箭舱')])
save(1212,{2:'长针火箭系统是一种火箭炮系统，大远征和荷鲁斯之乱期间曾安装在部分星际战士曲射手臼炮载具上。它由一组无制导火箭发射架组成，以连续齐射轰击敌军，尤其适合消灭密集步兵、轻型载具和防护薄弱的建筑。',4:'Arquitor Bombard with Spicula Rocket System 装备长针火箭系统的曲射手臼炮载具'},terms=[('Spicula Rocket System','长针火箭系统')])
save(1213,{2:'贝利卡图斯导弹阵列是原铸星际战士脉冲战车使用的一种导弹发射武器，常用于为作战小队提供额外火力支援。',4:'Bellicatus Missile Array mounted on top of a Impulsor 安装在脉冲战车顶部的贝利卡图斯导弹阵列'},terms=[('Bellicatus Missile Array','贝利卡图斯导弹阵列')])
save(1214,{3:'旋风战车使用的标准弹药。复仇导弹是一种配有近炸引信的高爆导弹，在接近目标时引爆，将致命破片撒向整片区域。',6:'一种防御性导弹，引爆后将地雷散布在大片区域，有效封阻敌方反击路线。每次射击布下的地雷数量充足，雷区能够维持到战斗结束。',9:'这种导弹以不稳定的化学弹头替代破片装药，用灼热烈焰覆盖爆炸区域，常用于攻击躲在建筑内部、受到防破片结构保护的目标。即使工事十分坚固，也难以挡住它；里面的守军即便侥幸未被烧死，多半也会死于随后残留的蒸气，身体由内而外遭到摧毁。'}, {6:'field指雷区，原译使“战场保持到战斗结束”不通；补清指代。'},[('Vengeance Missile','复仇导弹'),('Castellan Missile','堡主导弹'),('Incendiary Castellan Missile','燃烧堡主导弹'),('Helios High Explosive Missile','赫利俄斯高爆导弹'),('Extended Range Missile','超远程导弹')])
save(1215,{2:'北风防空导弹是德雷都无畏机甲使用的一种防空导弹，配有自导瞄准系统，可攻击与机甲主武器不同的目标。',4:'Deredeo Dreadnought with carapace-mounted Boreas Air Defence Missiles 顶部装有北风防空导弹的德雷都无畏机甲'},terms=[('Boreas Air Defence Missile','北风防空导弹')])
save(1216,{},terms=[('Stormfury Missile','风暴之怒导弹')])
save(1217,{2:'风暴打击导弹是星际战士使用的一种导弹，爆炸时发出雷鸣般的轰响，使爆炸范围内的敌人踉跄失衡、丧失方向感。风暴鸦炮艇、风暴牙和黑星渡鸦炮艇都可搭载这种武器。'},terms=[('Stormstrike Missile','风暴打击导弹')])
